public class Audit{public record Result(java.util.HashSet<CodeKey>unique,java.util.HashMap<CodeKey,Integer>counts){}public static Result count(String[]codes){var unique=new java.util.HashSet<CodeKey>();var counts=new java.util.HashMap<CodeKey,Integer>();for(String code:codes){CodeKey key=new CodeKey(code);unique.add(key);counts.merge(key,1,Integer::sum);}return new Result(unique,counts);}}
